style.css:
/* ChatGPT - Ice Blue Theme */
/* Background */
body {
    background-color: #d8f0ff !important; /* Soft ice blue */
}

/* Chat Bubbles */
div[class*="message"] {
    background: rgba(180, 220, 255, 0.6) !important; /* Frosted blue */
    border-radius: 10px !important;
    padding: 12px !important;
}

/* User Messages */
div[class*="message user"] {
    background: rgba(130, 190, 255, 0.8) !important; /* Deeper blue */
}

/* AI Responses */
div[class*="message assistant"] {
    background: rgba(220, 240, 255, 0.8) !important; /* Lighter blue */
}

/* Buttons */
button {
    background: #A7C7A3 !important; /* Soft sage green */
    color: #002244 !important;
    border-radius: 8px !important;
    padding: 10px !important;
    font-weight: bold !important;
}

/* Links */
a {
    color: #0077cc !important;
}

/* Input Box */
textarea {
    background: white !important;
    border: 1px solid #a7c7a3 !important;
    color: #002244 !important;
    border-radius: 8px !important;
}

/* Hide Scrollbar */
::-webkit-scrollbar {
    display: none;
}
